export const createQuizBodyPassingScoreMax = 100;




export const CreateQuizBody = zod.object({
  "title": zod.string().min(createQuizBodyTitleMin),
  "subjectId": zod.int(),
  "lessonId": zod.int().nullish(),
  "description": zod.string(),
  "passingScore": zod.number().min(createQuizBodyPassingScoreMin).max(createQuizBodyPassingScoreMax),
  "timeLimit": zod.int().min(1).nullish(),
  "status": zod.enum(['published', 'draft', 'archived'])
})

export const CreateQuizResponse = zod.object({
  "id": zod.int(),
  "title": zod.string(),
  "subjectId": zod.int(),
  "subjectName": zod.string(),
  "lessonId": zod.int().nullable(),
  "questionCount": zod.int(),
  "passingScore": zod.number(),
  "timeLimit": zod.int().nullable(),
  "status": zod.enum(['published', 'draft', 'archived']),
  "attempts": zod.int(),
  "bestScore": zod.number().nullable()
})


