/**
 * @summary List questions for a quiz
 */



export const ListQuestionsParams = zod.object({
  "id": zod.coerce.number().int().min(1)
})

export const ListQuestionsResponseItem = zod.object({
  "id": zod.int(),
  "number": zod.int(),
  "text": zod.string(),
  "type": zod.enum(['multiple_choice', 'true_false']),
  "choices": zod.array(zod.object({
  "id": zod.string(),
  "label": zod.string(),
  "value": zod.string()
})),
  "points": zod.int()
}).and(zod.object({
  "correctAnswer": zod.string()
}))
export const ListQuestionsResponse = zod.array(ListQuestionsResponseItem)


